/bin/bash -lc "python3 --version; python3 - <<'PY'
mods=['numpy','pandas','scipy','statsmodels','pydeseq2']
for m in mods:
    try:
        mod=__import__(m)
        print(m, getattr(mod,'__version__','ok'))
    except Exception as e:
        print(m, 'MISSING', type(e).__name__, str(e)[:80])
PY"

